pub fn fail(engine: *engine_mod.Engine, err: anyerror) c.JSValue {
    if (err == error.JavaScriptException) return engine.throwCaptured();
    if (err == error.ExecutionTerminated) return engine.throwExecutionTerminated();
    if (err == error.OutOfMemory) return engine.throwNativeOutOfMemoryFatal();
    return c.JS_ThrowTypeError(engine.context, "Native coding SDK: %s", @as([*:0]const u8, @errorName(err)));
}

// A cancelled native call can still return this explicit abrupt error
// after its private pending slot has been cleared by the actual cancel.
native_aborted: bool = false,
finished: bool = false,

pub fn initAction(engine: *em.Engine, result: anyerror!p.af.Action) Completion {
    var selected: ?p.af.Action = null;
    var native_aborted = false;
    if (result) |action| {
        selected = action;
    } else |err| {
        // Surface actual pending/current invocation events independently
        // BEFORE inspecting a failed-operation diagnostic ownership slot.
        _ = engine.nativeCallbackResult(c.pi_js_undefined());
        if (err == error.ExecutionTerminated) {
            native_aborted = true;
        } else if (err == error.JavaScriptException and !c.JS_HasException(engine.context) and engine.captured_exception != null) {
            const reason = engine.captured_exception.?;
            engine.captured_exception = null;
            selected = .{ .thrown = reason }; // Owned DATA; never flag/tag infer.
        } else {
            // Direct trusted GPA and non-JS host failures become actual
            // producer exits before any owned temporary is released.
            _ = @import("native_sdk.zig").fail(engine, err);
        }

        .thrown => |reason| self.owner.engine.checked(c.JS_Throw(self.owner.engine.context, reason)),
        .awaited => unreachable,
    };
}
pub fn finishVoid(self: *Completion) anyerror!void {
    switch (try self.finishAction()) {
        .returned => |value| self.owner.engine.freeValue(value),
        .thrown => |reason| { _ = try self.owner.engine.checked(c.JS_Throw(self.owner.engine.context, reason)); unreachable; },
        .awaited => unreachable,
    }
}

fn deliver(self: *Owner, event: *uv.PiUvEvent, abandoned: bool) !void {
    if (uv.pi_uv_event_info(event).kind == uv.PI_UV_NATIVE_ALLOCATION_FAILURE)
        return error.OutOfMemory;
    const selected = try self.eventClient(event);
    if (abandoned) return selected.abandon(selected.raw, event);
    return selected.complete(selected.raw, event);
}
fn poll(raw: *anyopaque) !bool {
    const self: *Owner = @ptrCast(@alignCast(raw));
    try self.hub.assertOwner();
    try self.hub.engine.checkNativeEntry();
    if (self.stopping or self.hub.stopping) return error.NativeEnvClosed;
    if (self.busy or c.JS_IsJobPending(self.hub.engine.runtime)) return false;
    // Preserve the actual TCP construction/callback reentry gate before
    // consuming any shared FIFO entry. FS uses its own same-owner gate.
    for (self.clients) |optional| if (optional) |selected|
        if (!selected.ready(selected.raw)) return false;
    const event = uv.pi_uv_service_next(self.service) orelse return false;
    self.busy = true;
    defer self.busy = false;
    const engine = self.hub.engine;
    engine.native_exception_diagnostics_suppressed += 1;
    defer engine.native_exception_diagnostics_suppressed -= 1;
    var completion = Completion.initVoid(engine, self.deliver(event, false));
    uv.pi_uv_event_release(event);
    try completion.finishVoid();
    return true; // The existing Hub owns the subsequent checkpoint.

var resource_index: usize = 0;
while (resource_index < self.resources.items.len) {
    const resource = self.resources.items[resource_index];
    if (resource.poll) |poll| {
        worked = (try poll(resource.raw)) or worked;
        if (c.JS_IsJobPending(engine.runtime)) return worked;
    }
    // Other native resources may retire during a callback. A scheduler
    // controller itself stays registered until teardown.
    if (resource_index < self.resources.items.len and self.resources.items[resource_index].raw == resource.raw) resource_index += 1;
}
return worked;

fn captureException(self: *Engine, context: *c.JSContext) anyerror {
    const exception = c.JS_GetException(context);
    return self.captureValue(context, exception, true);
}

/// Consumes exception. actual_event is supplied only by JS_GetException;
/// settled Promise rejection DATA never gains fatal authority from its bit.
fn captureValue(self: *Engine, context: *c.JSContext, exception: c.JSValue, actual_event: bool) anyerror {
    var owned: NativePending = .{
        .reason = exception,
        .fatal = actual_event and c.JS_PiNativePendingPriority(self.runtime, exception) > 0,
        .actual_event = actual_event,
    };
    if (owned.isFatal(self.runtime)) self.recordNativeFatal(exception);
    if (self.currentNativeFatal()) |first| {
        if (actual_event) _ = c.JS_PiNativePendingReplaceClassified(self.runtime,
            first, true, exception, owned.fatal);
        owned = .{ .reason = c.JS_DupValue(context, first), .fatal = true };
        self.releaseNativeOwned(exception, &owned);
    }
    self.takeNativePending(&owned);
    // A native implementation may call guest functions whose exceptions
    // are still inside a guest try/catch. Capturing their identity must
    // not invoke user ToString code before that catch gets the exception.
    var diagnostic_message: ?[]u8 = null;
    if (self.native_exception_diagnostics_suppressed == 0 and
        !owned.isFatal(self.runtime) and !c.JS_PiIsExecutionTermination(owned.reason.?)) {
        const text = c.JS_ToCString(context, owned.reason.?);
        self.takeNativePending(&owned);
        if (text != null) {
            if (!owned.isFatal(self.runtime) and !c.JS_PiIsExecutionTermination(owned.reason.?)) diagnostic_message = self.gpa.dupe(u8, std.mem.span(text)) catch null;
            c.JS_FreeCString(context, text);
            self.takeNativePending(&owned);
        }
    }
    // String conversion can invoke user code and another native callback.
    // Commit ownership only afterward, retaining the original thrown value.
    while (c.JS_HasException(self.context) or self.captured_exception != null or self.last_error != null) {
        self.takeNativePending(&owned);
        if (self.captured_exception) |previous| {
            self.captured_exception = null;
            self.releaseNativeOwned(previous, &owned);
        } else if (self.last_error) |message| {
            // A released diagnostic may reenter checked()/captureValue
            // and publish another owned message. Detach before freeing;
            // drain all channels before committing this invocation's text.
            self.last_error = null;
            self.gpa.free(message);
        }
    }
    if (c.JS_PiIsExecutionTermination(owned.reason.?)) {
        if (diagnostic_message) |message| self.gpa.free(message);
        _ = self.throwNativePending(&owned);
        return error.ExecutionTerminated;
    }
    if (owned.isFatal(self.runtime)) {
        if (diagnostic_message) |message| self.gpa.free(message);
        c.JS_SetUncatchableError(context, owned.reason.?);
    } else self.last_error = diagnostic_message;
    self.captured_exception = owned.reason.?;
    return error.JavaScriptException;

        f.queued_inside_callback = true;
        if (self.fail_first) {
            _ = c.JS_Throw(f.engine.context, a.duplicate(f.engine, f.reason.?));
            return error.JavaScriptException;
        }
        return;
    }
    if (self.release_in_callback and self.held_native_pointer) {
        self.held_native_pointer = false;
        try self.state.releaseNative();
        // The outer Wrapper remains the one live native pointer until return.
        f.last_pointer_in_callback = self.state.native_references == 1;
    }
    switch (self.failure) {
        .none => {},
        .host => return error.ActualReqWrapSelectedCallbackFailure,
        .ordinary => {
            _ = c.JS_Throw(f.engine.context, a.duplicate(f.engine, f.reason.?));
            return error.JavaScriptException;
        },
        .fatal => {
            _ = f.engine.throwNativeOutOfMemoryFatal();
            return error.JavaScriptException;
        },
    }
}

fn pump(self: *Fixture) !void {
    const until = physical.uv_hrtime() + 10 * std.time.ns_per_s;
    while (self.env().requests.waiting != 0) {
        if (c.JS_IsJobPending(self.engine.runtime)) return error.UnselectedReqWrapTaskQueue;
        const pump_native = self.engine.native_env_pump orelse return error.ActualReqWrapHubRequired;
        _ = try pump_native(self.engine);
        if (self.env().requests.waiting == 0) break;
        if (physical.uv_hrtime() >= until) return error.ActualReqWrapCompletionTimeout;
        physical.uv_sleep(1);
    }
}
fn takeCaught(self: *Fixture) !c.JSValue {
    const actual = self.engine.captured_exception orelse return error.ActualReqWrapReasonRequired;
    self.engine.captured_exception = null;
    return actual;

fn expectRetired(f: *Fixture, count: usize) !void {
    try std.testing.expectEqual(count, f.retired);
    try std.testing.expectEqual(count, f.destroyed);
    try std.testing.expectEqual(@as(c_int, 0), f.env().requests.waiting);
    try std.testing.expect(f.env().requests.head == null and f.env().requests.tail == null);
}
